  public async sendHumanLikeMessage(jid: string, text: string, incomingText?: string, messageKey?: any): Promise<any> {
    if (!this.sock) return null;

    // Safety Circuit-Breaker Check (Emergency 24-hour Auto Pause)
    if (whatsappSessionHealthEngine.isPaused()) {
      console.warn("[WhatsAppBot] 🛑 Outbound dispatch prevented: Emergency 24-Hour Safety Circuit-Breaker active.");
      return null;
    }

    // 7-Day Account Warm-Up Quota Check (Prevents bans on new numbers)
    const warmupCheck = whatsappSessionHealthEngine.canSendWarmupMessage();
    if (!warmupCheck.allowed) {
      console.warn(`[WhatsAppBot] 🛑 ${warmupCheck.reason}`);
      return null;
    }

    const formatted = this.formatWhatsAppMarkdown(text);
    const trimmed = formatted.trim();
    const recipientKey = jid.replace(/@.*$/, "");

    await humanBotFirewallService.simulateWhatsAppHumanTyping(
      this.sock,
      jid,
      messageKey,
      incomingText || "",
      trimmed
    );

    humanBotFirewallService.recordDispatchedMessage("whatsapp", recipientKey);
    whatsappSessionHealthEngine.recordOutboundMessage();

    // Anti-Hash Zero-Width Entropy Injection: creates a 100% unique cryptographic fingerprint
    // for every message while remaining 100% invisible to human recipients.
    const antiHashText = humanBotFirewallService.injectAntiHashZeroWidthEntropy(trimmed);

    const sendOptions: any = {};
    if (messageKey) {
      if (messageKey.message) {
        sendOptions.quoted = messageKey;
      } else {
        const cleanKey = messageKey.key || messageKey;
        sendOptions.quoted = {
          key: cleanKey,
          message: { conversation: incomingText || "..." },
        };
      }
    }

    let result: any = null;
    try {
      result = await this.sock.sendMessage(jid, { text: antiHashText }, sendOptions);
    } catch (quotedErr) {
      result = await this.sock.sendMessage(jid, { text: antiHashText });
    }

    if (result?.key?.id) {
      this.trackSentMessageId(result.key.id);

      // Record Friday's reply in whatsappHistoryEngine cache so chat context knows what Friday already said!
      const ts = Date.now();
      const botOutgoing: IncomingMessage = {
        id: result.key.id,
        senderPhone: "bot",
        senderName: "Friday",
        senderDisplayName: "Friday",
        replyJid: jid,
        groupId: jid.endsWith("@g.us") ? jid : null,
        groupName: null,
        isGroup: jid.endsWith("@g.us"),
        isUnknownContact: false,
        text: trimmed,
        timestamp: ts,
        dateStr: new Date(ts).toLocaleString("en-IN", {
          timeZone: "Asia/Kolkata",
          day: "numeric",
          month: "short",
          hour: "2-digit",
          minute: "2-digit",
        }),
        isRead: true,
      };
      baileysLiveStore.recordOutgoing(jid, trimmed, "Friday", true, result.key.id);
      whatsappHistoryEngine.unshiftMessage(botOutgoing);
      whatsappHistoryEngine.saveToFirestore(botOutgoing).catch(() => {});
    }
    return result;
  }

